// ====================================================================
// УЗЕЛ: АВТОРИЗАЦИЯ И МАРШРУТИЗАЦИЯ (РЕЖИМ «СЕНТЯБРЬ СОЛО» — АЛМАТЫ)
// ====================================================================
const fs = require('fs');
// ---------- TENDERSNIPER: ЕДИНАЯ КОНФИГУРАЦИЯ (вставляется сборщиком build.py) ----------
const TS_CONFIG = {
  ADMIN_CHAT_ID: 681740470,
  AUTHORIZED_USER_IDS: [681740470],
  N8N_DIR: '/home/node/.n8n',
  REGISTRY_PATH: '/home/node/.n8n/tendersniper_registry.json',
  LOCK_PATH: '/home/node/.n8n/tendersniper_scan.lock',
  LOCK_TIMEOUT_MS: 20 * 60 * 1000,
  RADAR_DB_PATH: '/home/node/.n8n/tendersniper_radar_db.json',
  RADAR_LOCK_PATH: '/home/node/.n8n/tendersniper_radar.lock',
  CHECKED_TTL_DAYS: 7,
  SENT_TTL_DAYS: 120,
  GEMINI_MODEL_DEFAULT: 'gemini-3.8-flash',
  BID_DISCOUNT: 0.10,
  SNR_TAX_RATE: 0.03,
  DIGEST_MIN_MARGIN: 15,
  DIGEST_ALT_MIN_PROFIT: 30000,
  DIGEST_ALT_MIN_MARGIN: 5,
  MIN_LOT_BUDGET: 0,
  MAX_LOT_BUDGET: 10000000,
  MIN_HOURS_TO_DEADLINE: 3,
  EXCLUDE_TRADE_METHOD_IDS: [],
  ALMATY_UTC_OFFSET: '+05:00',
  SCAN_TIMES_TEXT: '20:20 и 22:20'
};
// Файловая блокировка сканирования. staticData n8n сохраняется только по завершении execution,
// поэтому не видна параллельным запускам; файл с эксклюзивным созданием ('wx') — видна сразу.
// lockPath — необязательный путь (по умолчанию блокировка сканирования основного бота).
function tsReadLock(fs, lockPath) {
  try { return JSON.parse(fs.readFileSync(lockPath || TS_CONFIG.LOCK_PATH, 'utf8')); } catch (e) { return null; }
}
function tsAcquireLock(fs, owner, source, lockPath) {
  lockPath = lockPath || TS_CONFIG.LOCK_PATH;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const fd = fs.openSync(lockPath, 'wx');
      fs.writeSync(fd, JSON.stringify({ owner: String(owner), source, ts: Date.now() }));
      fs.closeSync(fd);
      return { ok: true };
    } catch (e) {
      if (e.code !== 'EEXIST') {
        console.warn('[LOCK WARN] Не удалось создать lock-файл, запуск без блокировки: ' + e.message);
        return { ok: true, degraded: true };
      }
      const cur = tsReadLock(fs, lockPath);
      const age = cur && cur.ts ? Date.now() - Number(cur.ts) : Infinity;
      if (age < TS_CONFIG.LOCK_TIMEOUT_MS) return { ok: false, lock: cur, ageMs: age };
      try { fs.unlinkSync(lockPath); } catch (e2) {}
    }
  }
  return { ok: false, lock: tsReadLock(fs, lockPath) };
}
function tsReleaseLock(fs, owner, lockPath) {
  lockPath = lockPath || TS_CONFIG.LOCK_PATH;
  const cur = tsReadLock(fs, lockPath);
  if (!cur) return false;
  if (owner !== undefined && owner !== null && String(cur.owner) !== String(owner)) return false;
  try { fs.unlinkSync(lockPath); return true; } catch (e) { return false; }
}
// Локальный реестр лотов: sent — отправленные в дайджест, checked — уже проверенные ИИ/вендор-локом.
// Не зависит от успешности записи в Google Sheets и не даёт повторно тратить Gemini на отклонённые лоты.
function tsLoadRegistry(fs) {
  try {
    const r = JSON.parse(fs.readFileSync(TS_CONFIG.REGISTRY_PATH, 'utf8'));
    return { checked: r.checked || {}, sent: r.sent || {} };
  } catch (e) {
    return { checked: {}, sent: {} };
  }
}
function tsSaveRegistry(fs, reg) {
  const now = Date.now();
  const checkedTtl = TS_CONFIG.CHECKED_TTL_DAYS * 86400000;
  const sentTtl = TS_CONFIG.SENT_TTL_DAYS * 86400000;
  const clean = { checked: {}, sent: {} };
  for (const [k, v] of Object.entries(reg.checked || {})) if (v && now - v.ts < checkedTtl) clean.checked[k] = v;
  for (const [k, v] of Object.entries(reg.sent || {})) if (v && now - v.ts < sentTtl) clean.sent[k] = v;
  try {
    const tmp = TS_CONFIG.REGISTRY_PATH + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(clean), 'utf8');
    fs.renameSync(tmp, TS_CONFIG.REGISTRY_PATH);
    return true;
  } catch (e) {
    console.warn('[REGISTRY WARN] Не удалось сохранить реестр: ' + e.message);
    return false;
  }
}
function tsLotKeys(lot) {
  return [lot.lotNumber, lot.lotId, lot.id].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(v => String(v).trim());
}
function tsIsKnownLot(reg, keys) {
  const now = Date.now();
  for (const k of keys) {
    if (reg.sent[k]) return 'sent';
    const c = reg.checked[k];
    if (c && now - c.ts < TS_CONFIG.CHECKED_TTL_DAYS * 86400000) return 'checked';
  }
  return null;
}
// ID из листа «История лотов»: только колонки с номером лота (не row_number / даты)
function tsHistoryIds(rows) {
  const ids = new Set();
  for (const r of rows) {
    for (const [k, v] of Object.entries(r || {})) {
      const lk = k.toLowerCase();
      if (lk === 'row_number' || lk.includes('дата')) continue;
      if (lk.includes('номер') || lk.includes('лот') || lk === 'id' || lk.endsWith('_id') || lk.endsWith('lotid')) {
        if (v !== undefined && v !== null && String(v).trim() !== '') ids.add(String(v).trim());
      }
    }
  }
  return ids;
}
// ---------- РАДАР ДЕМПИНГА: база итогов закупок и оценка риска лота ----------
// База (пишет только Radar Collector): TS_CONFIG.RADAR_DB_PATH
// lots[lotId] = { t: trdBuyId, a: номер объявления, c: БИН заказчика, n: название, k: категория, b: бюджет лота,
//                 q: количество, dmp: флаг Lots.dumping, m: способ закупки, dt: дата договора,
//                 w: БИН победителя, wa: сумма победителя, dp: скидка победителя (доля 0..1),
//                 bids: [[БИН, сумма заявки], ...] по возрастанию, nb: число заявок }

const TS_RADAR_CATEGORIES = [
  ['consumables', 'расходники', /картридж|тонер|чернил|фотобарабан|драм-?картридж|барабан|фотовал|термоплён|термоплен/],
  ['peripherals', 'периферия', /клавиатур|мыш[ьи]|наушник|гарнитур|колонк|веб-?камер|web-?камер|коврик/],
  ['mfp', 'МФУ', /мфу|многофункциональн/],
  ['printer', 'принтеры', /принтер|плоттер/],
  ['laptop', 'ноутбуки', /ноутбук|лэптоп|портативн[а-я]* компьютер/],
  ['aio', 'моноблоки', /моноблок/],
  ['monitor', 'мониторы', /монитор/],
  ['tablet', 'планшеты', /планшет/],
  ['server', 'серверы', /сервер/],
  ['pc', 'компьютеры', /системн[а-я]* блок|компьютер|рабоч[а-я]* станци/],
  ['ups', 'ИБП', /ибп|бесперебойн|стабилизатор/],
  ['network', 'сеть', /коммутатор|маршрутизатор|роутер|точк[аи] доступа|сетев[а-я]* оборудован|медиаконвертер|wi-?fi/],
  ['cctv', 'видеонаблюдение', /видеонаблюд|видеокамер|ip-?камер|видеорегистратор|камер/],
  ['projector', 'проекторы', /проектор|интерактивн/],
  ['cable', 'кабель', /кабел|патч-?корд|витая пара|удлинител|сетевой фильтр/],
  ['phone', 'телефоны', /телефон|смартфон|радиостанц/],
  ['scanner', 'сканеры', /сканер/],
  ['storage', 'накопители', /накопител|ssd|жёстк|жестк|флеш|карт[аы] памяти/]
];
function tsRadarCategory(name) {
  const t = String(name || '').toLowerCase();
  for (const [key, , re] of TS_RADAR_CATEGORIES) if (re.test(t)) return key;
  return 'other';
}
function tsRadarCategoryLabel(key) {
  const row = TS_RADAR_CATEGORIES.find(r => r[0] === key);
  return row ? row[1] : 'прочее';
}
function tsRadarBand(budget) {
  const b = Number(budget) || 0;
  return b < 150000 ? 'S' : (b < 1000000 ? 'M' : 'L');
}

function tsRadarEmptyDb() {
  return { version: 1, updatedAt: null, lots: {}, suppliers: {}, customers: {}, queue: {}, done: {}, kwCursor: 0 };
}
function tsLoadRadarDb(fs) {
  try {
    const db = JSON.parse(fs.readFileSync(TS_CONFIG.RADAR_DB_PATH, 'utf8'));
    return Object.assign(tsRadarEmptyDb(), db);
  } catch (e) {
    return tsRadarEmptyDb();
  }
}
function tsSaveRadarDb(fs, db) {
  db.updatedAt = new Date().toISOString();
  const tmp = TS_CONFIG.RADAR_DB_PATH + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(db), 'utf8');
  fs.renameSync(tmp, TS_CONFIG.RADAR_DB_PATH);
}

function tsRadarQuantile(arr, q) {
  if (!arr.length) return null;
  const s = arr.slice().sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos), hi = Math.ceil(pos);
  return s[lo] + (s[hi] - s[lo]) * (pos - lo);
}

// Индекс для быстрых оценок (строится один раз на запуск дайджеста)
function tsRadarBuildIndex(db) {
  const byCustomer = new Map();
  const byCatBand = new Map();
  const byCat = new Map();
  const supplier = new Map();
  const push = (m, k, v) => { let a = m.get(k); if (!a) { a = []; m.set(k, a); } a.push(v); };
  for (const lot of Object.values(db.lots || {})) {
    if (lot.c) push(byCustomer, lot.c, lot);
    push(byCatBand, lot.k + '|' + tsRadarBand(lot.b), lot);
    push(byCat, lot.k, lot);
    for (const [bin, amount] of (lot.bids || [])) {
      let s = supplier.get(bin);
      if (!s) { s = { part: 0, wins: 0, discs: [] }; supplier.set(bin, s); }
      s.part++;
      if (lot.w === bin) s.wins++;
      if (lot.b > 0 && amount > 0) s.discs.push(1 - amount / lot.b);
    }
  }
  return { db, byCustomer, byCatBand, byCat, supplier };
}

function tsRadarSupplierName(index, bin) {
  const dbName = index.db.suppliers && index.db.suppliers[bin];
  const seed = (typeof TS_RADAR_SEED !== 'undefined') ? TS_RADAR_SEED[bin] : null;
  return dbName || (seed && seed.name) || ('БИН ' + bin);
}
function tsRadarIsDumper(index, bin) {
  const seed = (typeof TS_RADAR_SEED !== 'undefined') ? TS_RADAR_SEED[bin] : null;
  if (seed && seed.dumper) return true;
  const s = index.supplier.get(bin);
  if (!s || s.discs.length < 3) return false;
  return tsRadarQuantile(s.discs, 0.5) >= 0.30;
}

// Оценка лота: на чём основана, ожидаемая скидка победителя, частые соперники у заказчика
function tsRadarAssess(index, lot) {
  const cat = tsRadarCategory(lot.name);
  const band = tsRadarBand(lot.budget);
  const withDisc = (arr) => (arr || []).filter(l => l.dp !== null && l.dp !== undefined);
  const custAll = index.byCustomer.get(lot.customerBin) || [];
  const custDisc = withDisc(custAll);
  const custCat = custDisc.filter(l => l.k === cat);
  const catBand = withDisc(index.byCatBand.get(cat + '|' + band));
  const catAll = withDisc(index.byCat.get(cat));

  let basis = null, sample = [];
  if (custCat.length >= 2) { basis = 'заказчик, ' + tsRadarCategoryLabel(cat); sample = custCat; }
  else if (custDisc.length >= 3) { basis = 'заказчик, все закупки'; sample = custDisc; }
  else if (catBand.length >= 5) { basis = 'Алматы, ' + tsRadarCategoryLabel(cat) + ', похожий бюджет'; sample = catBand; }
  else if (catAll.length >= 5) { basis = 'Алматы, ' + tsRadarCategoryLabel(cat); sample = catAll; }

  const discs = sample.map(l => l.dp);
  const bidders = sample.map(l => l.nb || (l.bids || []).length).filter(n => n > 0);

  // Частые соперники у этого заказчика
  const counts = new Map();
  for (const l of custAll) {
    for (const [bin] of (l.bids || [])) {
      const c = counts.get(bin) || { part: 0, wins: 0 };
      c.part++;
      if (l.w === bin) c.wins++;
      counts.set(bin, c);
    }
  }
  const competitors = [...counts.entries()]
    .sort((x, y) => (y[1].wins - x[1].wins) || (y[1].part - x[1].part))
    .slice(0, 3)
    .map(([bin, c]) => {
      const s = index.supplier.get(bin);
      return { bin, name: tsRadarSupplierName(index, bin), part: c.part, wins: c.wins,
        medDisc: s && s.discs.length ? tsRadarQuantile(s.discs, 0.5) : null, dumper: tsRadarIsDumper(index, bin) };
    });

  return {
    category: cat,
    basis,
    n: sample.length,
    customerLots: custAll.length,
    expDiscount: discs.length ? tsRadarQuantile(discs, 0.5) : null,
    p25: discs.length ? tsRadarQuantile(discs, 0.25) : null,
    p75: discs.length ? tsRadarQuantile(discs, 0.75) : null,
    avgBidders: bidders.length ? bidders.reduce((a, b) => a + b, 0) / bidders.length : null,
    competitors,
    hasDumper: competitors.some(c => c.dumper)
  };
}

// Экономика при ожидаемой цене победителя и безубыточная цена (налог СНР от выручки)
function tsRadarEconomics(assess, fin) {
  const budget = Number(fin.budget) || 0;
  const costs = (Number(fin.totalCost) || 0) + (Number(fin.logistics) || 0);
  const tax = TS_CONFIG.SNR_TAX_RATE;
  const breakeven = Math.ceil(costs / (1 - tax));
  const maxDiscount = budget > 0 ? 1 - breakeven / budget : null;
  let expPrice = null, profitAtExp = null;
  if (assess.expDiscount !== null && budget > 0) {
    expPrice = Math.round(budget * (1 - assess.expDiscount));
    profitAtExp = expPrice - costs - Math.round(expPrice * tax);
  }
  let risk;
  if (assess.expDiscount === null) risk = assess.hasDumper ? 'medium' : 'unknown';
  else if (profitAtExp < 0) risk = 'high';
  else if (assess.hasDumper || (maxDiscount !== null && maxDiscount - (assess.p75 === null ? assess.expDiscount : assess.p75) < 0.03)) risk = 'medium';
  else risk = 'low';
  return { breakeven, maxDiscount, expPrice, profitAtExp, risk };
}

const TS_RADAR_RISK_LABEL = { high: '🔴 ВЫСОКИЙ', medium: '🟠 СРЕДНИЙ', low: '🟢 НИЗКИЙ', unknown: '❔ НЕТ ДАННЫХ' };

function tsRadarLines(assess, econ, esc) {
  const pct = (x) => Math.round(x * 100) + '%';
  const kzt = (n) => Math.round(n || 0).toLocaleString('ru-RU') + ' ₸';
  const lines = [];
  let head = '   ⚔️ Риск демпинга: <b>' + TS_RADAR_RISK_LABEL[econ.risk] + '</b>';
  if (assess.expDiscount !== null) {
    head += ' — скидка победителя обычно ' + pct(assess.expDiscount) +
      (assess.p25 !== null && assess.p75 !== null && assess.n >= 3 ? ' (' + pct(assess.p25) + '–' + pct(assess.p75) + ')' : '') +
      ', участников ~' + (assess.avgBidders ? Math.round(assess.avgBidders) : '?') +
      ' <i>[' + esc(assess.basis) + ', ' + assess.n + ' закуп.]</i>';
  } else {
    head += assess.customerLots ? ' — у заказчика ' + assess.customerLots + ' закуп. без итогов' : ' — истории по заказчику и категории пока нет';
  }
  lines.push(head);
  if (assess.competitors.length) {
    lines.push('   • Соперники у заказчика: ' + assess.competitors.map(c =>
      (c.dumper ? '⚠️' : '') + esc(c.name) + ' (' + c.part + ' уч., ' + c.wins + ' поб.' + (c.medDisc !== null ? ', обычно −' + pct(c.medDisc) : '') + ')').join('; '));
  }
  const tail = [];
  if (econ.expPrice !== null) tail.push('при ~' + kzt(econ.expPrice) + ' ваш результат: <b>' + (econ.profitAtExp >= 0 ? '+' : '') + kzt(econ.profitAtExp) + '</b>');
  if (econ.maxDiscount !== null) tail.push('ваш предел: ' + kzt(econ.breakeven) + ' (−' + pct(Math.max(0, econ.maxDiscount)) + ')');
  if (tail.length) lines.push('   • ' + tail.join(' | '));
  return lines;
}
const inputData = $input.first()?.json || {};

// 1. Конфигурация доступа — только числовые Telegram ID (username можно сменить/перехватить)
const DEFAULT_ADMIN_CHAT_ID = TS_CONFIG.ADMIN_CHAT_ID;
const AUTHORIZED_USER_IDS = new Set(TS_CONFIG.AUTHORIZED_USER_IDS.map(Number));

let execId = null;
try { execId = $execution?.id; } catch (e) {}
if (!execId) execId = 'manual-' + Date.now();

// 2. Определение источника (CRON или TELEGRAM)
const msg = inputData.message || inputData.edited_message || inputData.callback_query?.message;
const isCron = !msg;

function reply(fields) {
  return [{
    json: Object.assign({
      isAuthorized: true,
      shouldRunPipeline: false,
      chatId: DEFAULT_ADMIN_CHAT_ID,
      source: 'UNKNOWN',
      userName: '',
      directReplyMessage: null,
      lockOwner: null
    }, fields)
  }];
}

if (isCron) {
  const lk = tsAcquireLock(fs, execId, 'CRON');
  if (!lk.ok) {
    console.log('[AUTH LOCK] Предыдущее сканирование ещё выполняется (' + Math.round((lk.ageMs || 0) / 1000) + ' c). Пропуск запуска CRON.');
    return [];
  }
  console.log('[AUTH] Запуск по расписанию (CRON). Целевой чат: ' + DEFAULT_ADMIN_CHAT_ID);
  return reply({ shouldRunPipeline: true, source: 'CRON', userName: 'Система (CRON)', lockOwner: execId });
}

// 3. Данные пользователя Telegram
const fromUser = inputData.message?.from || inputData.edited_message?.from || inputData.callback_query?.from || {};
const userId = fromUser.id ? Number(fromUser.id) : null;
const username = fromUser.username ? String(fromUser.username).toLowerCase() : null;
const chatId = msg?.chat?.id || userId || DEFAULT_ADMIN_CHAT_ID;
const fullName = [fromUser.first_name, fromUser.last_name].filter(Boolean).join(' ') || 'Пользователь';
const rawText = String(inputData.message?.text || inputData.edited_message?.text || inputData.callback_query?.data || '').trim();
// "/scan@TenderBot extra" -> "/scan"
const command = (rawText.split(/\s+/)[0] || '').replace(/@[\w_]+$/, '').toLowerCase();

// 4. Проверка авторизации
const isAuthorized = !!(userId && AUTHORIZED_USER_IDS.has(userId));

if (!isAuthorized) {
  console.warn('[SECURITY WARN] Попытка несанкционированного доступа! ID: ' + userId + ', Username: @' + (username || 'none') + ', Имя: ' + fullName + ', Текст: "' + rawText.substring(0, 100) + '"');
  return reply({
    isAuthorized: false,
    chatId,
    source: 'UNAUTHORIZED',
    userName: fullName,
    directReplyMessage:
      '⛔ <b>Доступ запрещён</b>\n\n' +
      'Ваш аккаунт (ID: <code>' + (userId || 'Unknown') + '</code>) не авторизован для управления радаром TenderSniper.\n\n' +
      'Обратитесь к администратору для добавления в белый список.'
  });
}

const escapeHtml = (t) => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// 5. /start и /help
if (command === '/start' || command === '/help') {
  const helpReply =
    '👋 <b>TenderSniper AI — Режим «Сентябрь Соло» (г. Алматы)</b>\n━━━━━━━━━━━━━━━━━━━━\n' +
    '👤 <b>Пользователь:</b> ' + escapeHtml(fullName) + ' (Авторизован ✅)\n' +
    '⏱ <b>Фоновый мониторинг:</b> ' + TS_CONFIG.SCAN_TIMES_TEXT + ' (Asia/Almaty), радар демпинга — 20:10–22:50\n' +
    '📍 <b>Регион:</b> Только город Алматы (КАТО 75*)\n' +
    '⚖️ <b>Методы закупок:</b> Все доступные (ЗЦП, ОИ, Открытый конкурс и др.)\n' +
    '⏳ <b>Дедлайн:</b> лоты, до окончания приёма которых меньше ' + TS_CONFIG.MIN_HOURS_TO_DEADLINE + ' ч, отбрасываются\n' +
    '🎯 <b>Критерии отбора:</b> 🟢 ТОЧНОЕ СОВПАДЕНИЕ и чистая маржа ≥ ' + TS_CONFIG.DIGEST_MIN_MARGIN + '% ' +
    '(или прибыль ≥ ' + TS_CONFIG.DIGEST_ALT_MIN_PROFIT.toLocaleString('ru-RU') + ' ₸ при марже ≥ ' + TS_CONFIG.DIGEST_ALT_MIN_MARGIN + '%)\n' +
    '📦 <b>Каталог:</b> Полная номенклатура Al-Style / ASBIS (без ограничений по остаткам)\n\n' +
    '📌 <b>Доступные команды:</b>\n' +
    '• <code>/scan</code> — запустить аудит алматинских лотов прямо сейчас\n' +
    '• <code>/status</code> — состояние радара (блокировка, реестр лотов)\n' +
    '• <code>/unlock</code> — снять зависшую блокировку сканирования\n' +
