// Безопасное чтение переменных окружения: $env может быть заблокирован (N8N_BLOCK_ENV_ACCESS_IN_NODE)
function tsGetEnv(name, fallback) {
  try { if (typeof $env !== 'undefined' && $env && $env[name]) return String($env[name]); } catch (e) {}
  try { if (typeof process !== 'undefined' && process.env && process.env[name]) return String(process.env[name]); } catch (e) {}
  return fallback === undefined ? '' : fallback;
}
// Локальный реестр лотов: sent — отправленные в дайджест, checked — уже проверенные ИИ/вендор-локом.
// Не зависит от успешности записи в Google Sheets и не даёт повторно тратить Gemini на отклонённые лоты.
function tsLoadRegistry(fs) {
  try {
    const r = JSON.parse(fs.readFileSync(TS_CONFIG.REGISTRY_PATH, 'utf8'));
    return { checked: r.checked || {}, sent: r.sent || {} };
  } catch (e) {
    return { checked: {}, sent: {} };
  }
}
function tsSaveRegistry(fs, reg) {
  const now = Date.now();
  const checkedTtl = TS_CONFIG.CHECKED_TTL_DAYS * 86400000;
  const sentTtl = TS_CONFIG.SENT_TTL_DAYS * 86400000;
  const clean = { checked: {}, sent: {} };
  for (const [k, v] of Object.entries(reg.checked || {})) if (v && now - v.ts < checkedTtl) clean.checked[k] = v;
  for (const [k, v] of Object.entries(reg.sent || {})) if (v && now - v.ts < sentTtl) clean.sent[k] = v;
  try {
    const tmp = TS_CONFIG.REGISTRY_PATH + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(clean), 'utf8');
    fs.renameSync(tmp, TS_CONFIG.REGISTRY_PATH);
    return true;
  } catch (e) {
    console.warn('[REGISTRY WARN] Не удалось сохранить реестр: ' + e.message);
    return false;
  }
}
function tsLotKeys(lot) {
  return [lot.lotNumber, lot.lotId, lot.id].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(v => String(v).trim());
}
function tsIsKnownLot(reg, keys) {
  const now = Date.now();
  for (const k of keys) {
    if (reg.sent[k]) return 'sent';
    const c = reg.checked[k];
    if (c && now - c.ts < TS_CONFIG.CHECKED_TTL_DAYS * 86400000) return 'checked';
  }
  return null;
}
// ID из листа «История лотов»: только колонки с номером лота (не row_number / даты)
function tsHistoryIds(rows) {
  const ids = new Set();
  for (const r of rows) {
    for (const [k, v] of Object.entries(r || {})) {
      const lk = k.toLowerCase();
      if (lk === 'row_number' || lk.includes('дата')) continue;
      if (lk.includes('номер') || lk.includes('лот') || lk === 'id' || lk.endsWith('_id') || lk.endsWith('lotid')) {
        if (v !== undefined && v !== null && String(v).trim() !== '') ids.add(String(v).trim());
      }
    }
  }
  return ids;
}
function makeWordRegex(pattern) {
  return new RegExp('(?<![a-zа-яё0-9])(' + pattern + ')(?![a-zа-яё0-9])', 'i');
}
// Единая финансовая модель (одинакова в Pre-Filter и Parse Gemini Verdict).
// Налоговый режим: СНР на основе упрощённой декларации — 3% от оборота (ФНО 910.00), без НДС и КПН.
const RE_LOG_SMALL = makeWordRegex('флеш[а-я]*|flash|usb|кабель[а-я]*|патч-корд[а-я]*|мышь|мыши|mouse|коврик[а-я]*|наушник[а-я]*|гарнитур[а-я]*|headset|адаптер[а-я]*|переходник[а-я]*|картридж[а-я]*|тонер[а-я]*|cartridge|toner|клавиатур[а-я]*');
const RE_LOG_HEAVY = makeWordRegex('сервер[а-я]*|стойк[а-я]*|server');
const RE_LOG_OFFICE = makeWordRegex('принтер[а-я]*|мфу|компьютер[а-я]*|системный[ \t]*блок|моноблок[а-я]*|монитор[а-я]*|ибп|проектор[а-я]*');

function calculateLogistics(productName, lotQty) {
  const isSmall = RE_LOG_SMALL.test(productName);
  let unitFee = 3000;
  if (RE_LOG_HEAVY.test(productName)) unitFee = 15000;
  else if (RE_LOG_OFFICE.test(productName)) unitFee = 4500;
  else if (isSmall) unitFee = 500;
  let baseCost = unitFee * lotQty;
  if (isSmall) baseCost = Math.min(baseCost, 6000);
  return Math.min(Math.max(baseCost, 3000), 150000);
}

function evaluateFinancials(lotBudget, unitPurchaseCost, lotQty, productName) {
  const targetBid = Math.round(lotBudget * (1 - TS_CONFIG.BID_DISCOUNT));
  const totalPurchase = Math.round(unitPurchaseCost * lotQty);
  const logisticsCost = calculateLogistics(productName || '', lotQty);
  const totalTax = Math.round(targetBid * TS_CONFIG.SNR_TAX_RATE);
  const totalExpenses = totalPurchase + logisticsCost + totalTax;
  const netProfit = targetBid - totalExpenses;
  const marginPercent = targetBid > 0 ? +((netProfit / targetBid) * 100).toFixed(1) : 0;

  let isViable = false;
  if (targetBid <= 100000) isViable = (netProfit >= 7000 && marginPercent >= 10);
  else if (targetBid <= 1000000) isViable = (netProfit >= 15000 && marginPercent >= 8);
  else isViable = (netProfit >= 40000 && marginPercent >= 6);

  return { targetBid, totalPurchase, logisticsCost, vatPayable: 0, citPayable: 0, totalTax, totalExpenses, netProfit, marginPercent, isViable };
}

function isDigestEligible(marginPercent, profit) {
  const m = Number(marginPercent) || 0;
  const p = Number(profit) || 0;
  return m >= TS_CONFIG.DIGEST_MIN_MARGIN || (p >= TS_CONFIG.DIGEST_ALT_MIN_PROFIT && m >= TS_CONFIG.DIGEST_ALT_MIN_MARGIN);
}
