    let req;
    const timer = setTimeout(() => { try { req && req.destroy(); } catch (e) {} done(reject, new Error('HTTP timeout (' + timeoutMs + 'ms)')); }, timeoutMs);
    const client = url.startsWith('https') ? httpsMod : httpMod;
